package com.shiphappens.logistics.entity;
import jakarta.persistence.*;
@Entity @Table(name="webhook_subscriptions") public class WebhookSubscription { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id") private Customer customer; @Column(name="target_url") private String targetUrl; private String secret; private boolean active=true; public Long getId(){return id;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public String getTargetUrl(){return targetUrl;} public void setTargetUrl(String v){targetUrl=v;} public String getSecret(){return secret;} public void setSecret(String v){secret=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
